import http from 'k6/http';
import exec from 'k6/execution';
import { check } from 'k6';
import { Counter, Trend } from 'k6/metrics';
const starts = new Counter('starts');
const steady = new Counter('steady_requests');
const latency = new Trend('steady_latency', true);
const h2 = __ENV.PROTOCOL !== 'h1';
const url = (h2 ? 'https' : 'http') + '://localhost:8080';
const path = __ENV.PATHNAME || '/echo';
const body = 'x'.repeat(Number(__ENV.BODY_BYTES || 1024));
const expected = path === '/echo' ? body : path === '/json' ? '{"message":"Hello, World!"}' : path.startsWith('/users/') ? '42' : 'Hello, World!';
const duration = __ENV.DURATION || '35s';
const vus = Number(__ENV.VUS || 64);
export const options = {
  scenarios: { load: __ENV.RATE ? { executor: 'ramping-arrival-rate', startRate: 100, timeUnit: '1s', stages: [{duration: '5s', target: Number(__ENV.RATE)}, {duration: `${parseInt(duration) - 5}s`, target: Number(__ENV.RATE)}], preAllocatedVUs: vus } : {executor: 'constant-vus', vus, duration}},
  tlsVersion: { min: 'tls1.3', max: 'tls1.3' },
  summaryTrendStats: ['med', 'p(99)', 'p(99.9)', 'max'],
  thresholds: {http_req_failed: ['rate==0'], checks: ['rate==1'], ...(__ENV.RATE ? {dropped_iterations: ['count==0']} : {})},
};
export default function () {
  starts.add(1);
  const r = path === '/echo' ? http.post(url + path, body) : http.get(url + path);
  check(r, {'status/body/H2': r => r.status === 200 && r.body === expected && r.proto === (h2 ? 'HTTP/2.0' : 'HTTP/1.1')});
  if (exec.instance.currentTestRunDuration >= 5000) {steady.add(1);latency.add(r.timings.duration);}
}
export function handleSummary(data) {return {[__ENV.RESULT]: JSON.stringify(data)};}

