use std::{os::unix::process::CommandExt, process::Command};
unsafe extern "C" {
    fn sched_setaffinity(pid: i32, size: usize, mask: *const u64) -> i32;
}
fn main() {
    let mut args = std::env::args().skip(1);
    let mask: u64 = args.next().unwrap().parse().unwrap();
    // Temporary measurement launcher: kernel reads exactly one u64 affinity mask.
    assert_eq!(unsafe { sched_setaffinity(0, 8, &mask) }, 0);
    panic!("{}", Command::new(args.next().unwrap()).args(args).exec());
}
